import AVFoundation
import CoreVideo
import Foundation

// Writes frames through AVAssetWriter into a .mov/.mp4, then exit(0) with no finishWriting: what
// NSApp's .terminateNow does to an export in flight. Second mode probes the file left behind.
let args = CommandLine.arguments
if args[1] == "probe" {
    let url = URL(fileURLWithPath: args[2])
    let size = (try? FileManager.default.attributesOfItem(atPath: url.path)[.size] as? Int) ?? -1
    print("exists:", FileManager.default.fileExists(atPath: url.path), "bytes:", size ?? -1)
    let asset = AVURLAsset(url: url)
    print("isPlayable:", asset.isPlayable, "isReadable:", asset.isReadable,
          "tracks:", asset.tracks.count, "duration:", CMTimeGetSeconds(asset.duration))
    exit(0)
}
let url = URL(fileURLWithPath: args[2])
try? FileManager.default.removeItem(at: url)
let type: AVFileType = url.pathExtension == "mp4" ? .mp4 : .mov
let writer = try AVAssetWriter(outputURL: url, fileType: type)
let input = AVAssetWriterInput(mediaType: .video, outputSettings: [
    AVVideoCodecKey: AVVideoCodecType.h264, AVVideoWidthKey: 1280, AVVideoHeightKey: 720,
])
input.expectsMediaDataInRealTime = false
let adaptor = AVAssetWriterInputPixelBufferAdaptor(assetWriterInput: input, sourcePixelBufferAttributes: [
    kCVPixelBufferPixelFormatTypeKey as String: REDACTED,
    kCVPixelBufferWidthKey as String: 1280, kCVPixelBufferHeightKey as String: 720,
])
writer.add(input)
writer.startWriting()
writer.startSession(atSourceTime: .zero)
var n: Int64 = 0
let start = Date()
while Date().timeIntervalSince(start) < 6 && n < 900 {
    if input.isReadyForMoreMediaData, let pool = adaptor.pixelBufferPool {
        var pb: CVPixelBuffer?
        CVPixelBufferPoolCreatePixelBuffer(nil, pool, &pb)
        CVPixelBufferLockBaseAddress(pb!, [])
        let base = CVPixelBufferGetBaseAddress(pb!)!.assumingMemoryBound(to: UInt8.self)
        let bytes = CVPixelBufferGetBytesPerRow(pb!) * 720
        for i in stride(from: 0, to: bytes, by: 97) { base[i] = UInt8(truncatingIfNeeded: Int(n) &* i) }
        CVPixelBufferUnlockBaseAddress(pb!, [])
        adaptor.append(pb!, withPresentationTime: CMTime(value: n, timescale: 30))
        n += 1
    } else {
        Thread.sleep(forTimeInterval: 0.005)
    }
}
print("appended", n, "frames; exiting with no finishWriting")
exit(0)

