import AppKit

// d19_quit <none|sheet> <menu|direct|key> [regular] [doc] [dismiss]
// A window, with or without a presentAsSheet sheet; does Quit reach applicationShouldTerminate,
// and does the process end? `doc` puts an NSDocument (clean) behind the window, as Frame Job has.
let args = CommandLine.arguments
let wantSheet = args[1] == "sheet"
let how = args[2]
let regular = args.contains("regular")
let useDoc = args.contains("doc")
let dirty = args.contains("dirty")
let dismissLater = args.contains("dismiss")

final class VC: NSViewController {
    override func loadView() { view = NSView(frame: NSRect(x: 0, y: 0, width: 400, height: 300)) }
}
final class SheetVC: NSViewController {
    override func loadView() { view = NSView(frame: NSRect(x: 0, y: 0, width: 200, height: 100)) }
}
final class Doc: NSDocument {
    override func data(ofType typeName: String) throws -> Data { Data() }
    override func read(from data: Data, ofType typeName: String) throws {}
    override class var autosavesInPlace: Bool { false }
}
final class D: NSObject, NSApplicationDelegate {
    var window: NSWindow!
    let vc = VC()
    let sheet = SheetVC()
    var doc: Doc?
    func applicationDidFinishLaunching(_ n: Notification) {
        let menu = NSMenu()
        let appItem = NSMenuItem()
        let sub = NSMenu()
        sub.addItem(withTitle: "Quit", action: #selector(NSApplication.terminate(_:)), keyEquivalent: "q")
        appItem.submenu = sub
        menu.addItem(appItem)
        NSApp.mainMenu = menu
        window = NSWindow(contentViewController: vc)
        if useDoc {
            let d = Doc()
            d.addWindowController(NSWindowController(window: window))
            NSDocumentController.shared.addDocument(d)
            if dirty { d.updateChangeCount(.changeDone) }
            doc = d
        }
        window.makeKeyAndOrderFront(nil)
        NSApp.activate(ignoringOtherApps: true)
        if wantSheet { vc.presentAsSheet(sheet) }
        DispatchQueue.main.asyncAfter(deadline: .now() + 1) {
            print("attachedSheet:", self.window.attachedSheet != nil, "active:", NSApp.isActive,
                  "key:", NSApp.keyWindow as Any)
            sub.update()
            print("quit item enabled:", sub.items[0].isEnabled)
            switch how {
            case "direct":
                print("NSApp.terminate(nil)")
                NSApp.terminate(nil)
            case "key":
                print("performKeyEquivalent ⌘Q through the main menu")
                let e = NSEvent.keyEvent(
                    with: .keyDown, location: .zero, modifierFlags: .command, timestamp: 0,
                    windowNumber: NSApp.keyWindow?.windowNumber ?? 0, context: nil,
                    characters: "q", charactersIgnoringModifiers: "q", isARepeat: false, keyCode: 12)!
                print("handled:", NSApp.mainMenu!.performKeyEquivalent(with: e))
            default:
                print("performActionForItem")
                sub.performActionForItem(at: 0)
            }
            print("returned from the Quit call")
            DispatchQueue.main.asyncAfter(deadline: .now() + 2) {
                print("ALIVE two seconds on; attachedSheets now:", NSApp.windows.map { $0.sheets.count })
                if dismissLater, wantSheet {
                    print("dismissing the sheet")
                    self.vc.dismiss(self.sheet)
                    DispatchQueue.main.asyncAfter(deadline: .now() + 2) {
                        print("ALIVE two seconds after the sheet closed")
                        exit(8)
                    }
                } else {
                    exit(7)
                }
            }
        }
    }
    func applicationShouldTerminate(_ s: NSApplication) -> NSApplication.TerminateReply {
        print("applicationShouldTerminate ran; answering terminateNow")
        return .terminateNow
    }
    func applicationWillTerminate(_ n: Notification) { print("applicationWillTerminate ran") }
}
setbuf(stdout, nil)
let app = NSApplication.shared
app.setActivationPolicy(regular ? .regular : .accessory)
let d = D()
app.delegate = d
app.run()

